// Vapi 'tool-calls' mesajindan ilk tool cagrisini cikar
const body = $json.body || $json;
const msg = body.message || {};
const tc = (msg.toolCallList && msg.toolCallList[0]) || (msg.toolCalls && msg.toolCalls[0]) || {};
let name = tc.name || (tc.function && tc.function.name) || '';
let args = tc.arguments || (tc.function && tc.function.arguments) || {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
return [{ json: {
  toolCallId: tc.id || '',
  tool: name,
  args,
  callerNumber: (msg.call && msg.call.customer && msg.call.customer.number) || ''
} }];

// Is saatleri icinde bos 30 dakikalik slotlari bul (ilk 4'unu soyle)
const TZ_NOTE = 'UK time'; // asistan Ingiliz pazarina konusuyor
const OPEN_H = 9, CLOSE_H = 18, SLOT_MIN = 30;
const date = $('Parse Tool Call').first().json.args.date; // YYYY-MM-DD
const events = $input.all().map(i => i.json).filter(e => e && (e.start || e.end));
const busy = events.map(e => ({
  s: new Date(e.start && (e.start.dateTime || e.start.date) || 0).getTime(),
  e: new Date(e.end && (e.end.dateTime || e.end.date) || 0).getTime()
}));
const free = [];
for (let h = OPEN_H; h < CLOSE_H && free.length < 4; h++) {
  for (let m = 0; m < 60 && free.length < 4; m += SLOT_MIN) {
    const s = new Date(`${date}T${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:00Z`).getTime();
    const e = s + SLOT_MIN * 60000;
    const clash = busy.some(b => s < b.e && e > b.s);
    if (!clash && s > Date.now()) free.push(`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`);
  }
}
const result = free.length
  ? `Available ${SLOT_MIN}-minute slots on ${date} (${TZ_NOTE}): ${free.join(', ')}. Offer at most two of these.`
  : `No free slots on ${date}. Ask for another weekday.`;
return [{ json: { result } }];

const p = $('Parse Tool Call').first().json;
const a = p.args || {};
return [{ json: {
  Timestamp: new Date().toISOString(),
  Name: a.name || '',
  Phone: a.phone || p.callerNumber || '',
  Email: a.email || '',
  Sector: a.sector || '',
  Datetime: a.datetime || '',
  Notes: a.notes || '',
  Status: 'Booked',
  Source: 'Voice agent'
} }];

