const p = $('Parse Tool Call').first().json;
const a = p.args || {};
return [{ json: {
  Timestamp: new Date().toISOString(),
  Name: a.name || '',
  Phone: a.phone || p.callerNumber || '',
  Email: a.email || '',
  Sector: a.sector || '',
  Datetime: '',
  Notes: a.need || '',
  Status: 'Callback requested',
  Source: 'Voice agent'
} }];

const p = $('Parse Tool Call').first().json;
let result = $json.result;
if (!result) {
  if (p.tool === 'book_consultation') {
    result = `Booked. ${p.args.name} is confirmed for ${p.args.datetime} (UK time). It is in the diary and a confirmation is on its way.`;
  } else if (p.tool === 'capture_lead') {
    result = `Saved. Tell the caller Ferit will personally call ${p.args.name || 'them'} back within one business day.`;
  } else {
    result = 'Unknown tool. Apologise briefly and offer to take a message instead.';
  }
}
return [{ json: { results: [{ toolCallId: p.toolCallId, result }] } }];

const m = ($json.body && $json.body.message) || {};
const art = m.artifact || {};
const an = m.analysis || {};
const sd = an.structuredData || {};
return [{ json: {
  Timestamp: new Date().toISOString(),
  Caller: (m.call && m.call.customer && m.call.customer.number) || (m.customer && m.customer.number) || 'web-call',
  DurationSec: Math.round(m.durationSeconds || (m.durationMs || 0) / 1000),
  EndedReason: m.endedReason || '',
  Sector: sd.sector || '',
  Booked: (sd.booked === true ? 'yes' : sd.booked === false ? 'no' : ''),
  Summary: an.summary || m.summary || '',
  Recording: art.recordingUrl || m.recordingUrl || '',
  Transcript: String(art.transcript || m.transcript || '').slice(0, 45000)
} }];

